export default {
  version: 1,
  name: "Settled Prop Shadow Bridge",
  description: "After a prop stays still for 30 ticks, its lantern-cast shadow becomes solid. The shadow lasts one tick and refreshes only while the prop remains still, so movement dissolves the bridge on the next simulation tick.",
  rules: [
    {
      id: "settled-prop-shadow",
      each: "prop",
      when: {
        all: [
          { compare: { left: { field: "stationaryTicks" }, op: "gte", right: 30 } },
          { compare: { left: { field: "speed" }, op: "eq", right: 0 } }
        ]
      },
      actions: [
        { type: "projectShadow", maxLength: 480, thickness: 12, lifetime: 1, solid: true }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Brass Prop Step",
  description: "A stationary prop glows brass while the courier is within 90 units. A solid step appears to its right, 32 units above its feet. The step lasts one tick and is renewed only while the courier remains nearby, so it expires when the courier moves away.",
  rules: [
    {
      id: "nearby-stationary-prop-step",
      each: "prop",
      when: {
        all: [
          { compare: { left: { field: "speed" }, op: "eq", right: 0 } },
          { compare: { left: { field: "distanceToPlayer" }, op: "lte", right: 90 } }
        ]
      },
      actions: [
        { type: "createSurface", offsetX: 56, offsetY: -32, width: 72, lifetime: 1, solid: true },
        { type: "cue", target: "self", color: "brass", intensity: 0.8 }
      ]
    }
  ]
} satisfies RuleModule;

export default {
  version: 1,
  name: "Solid Shadows",
  description: "While a crate is still, its shadow from a lit lantern becomes a solid bridge you can walk across.",
  rules: [
    {
      id: "still-prop-shadow-bridge",
      each: "prop",
      on: "tick",
      when: {
        compare: {
          left: { field: "stationaryTicks" },
          op: "gte",
          right: 1
        }
      },
      actions: [
        {
          type: "projectShadow",
          maxLength: 480,
          thickness: 10,
          lifetime: 1,
          solid: true
        }
      ]
    }
  ]
} satisfies RuleModule;
